mutations.find:
if (drawingChip) {
  // Words, not a number: the cell drops `num` and its monospace.
  nominalCell.className = "tvcell tvcell--nominal tvcell--drawing";
  nominalCell.appendChild(drawingChip);
}

mutations.replace:
if (drawingChip) {
  // Words, not a number: the cell drops `num` and its monospace.
  nominalCell.className = "tvcell tvcell--nominal tvcell--drawing";
}
